nativeConfigTemplate:
user "root";
daemon off;
master_process off;
pid "<private-prefix>/nginx.pid";
error_log "<private-prefix>/error.log" warn;
events { worker_connections 1024; }
http {
  access_log off;
  default_type application/octet-stream;
  sendfile on;
  tcp_nopush on;
  keepalive_timeout 30s;
  keepalive_requests 1000000;
  client_body_temp_path "<private-prefix>/body-temp";
  proxy_temp_path "<private-prefix>/proxy-temp";
  upstream fixture { server 127.0.0.1:<origin-port>; keepalive 128; }
  server {
    listen 127.0.0.1:<front-port>;
    server_name localhost;
    location = /static { alias "<private-prefix>/payload.bin"; }
    location = /proxy {
      proxy_http_version 1.1;
      proxy_set_header Connection "";
      proxy_connect_timeout 1s;
      proxy_read_timeout 2s;
      proxy_pass http://fixture/static;
    }
  }
}
